// Decides whether the digest must be sent in this run.
// The manual path always continues. The scheduled path continues only when the
// current hour and weekday in America/Bogota match send_hour and send_days.
const config = {};
for (const row of $('Config').all()) {
  const key = String(row.json.key ?? '').trim();
  if (key) config[key] = String(row.json.value ?? '').trim();
}

const manual = $('Manual Trigger').isExecuted;

const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Bogota',
  weekday: 'short',
  hour: 'numeric',
  hourCycle: 'h23',
}).formatToParts(new Date());
const hour = Number(parts.find((p) => p.type === 'hour').value);
const weekday = parts.find((p) => p.type === 'weekday').value.toLowerCase();

const sendHour = Number(config.send_hour);
const sendDays = (config.send_days ?? '')
  .toLowerCase()
  .split(',')
  .map((d) => d.trim())
  .filter(Boolean);

const hourOk = config.send_hour !== undefined && config.send_hour !== '' && sendHour === hour;
const dayOk = sendDays.includes('all') || sendDays.includes(weekday);

if (!manual && !(hourOk && dayOk)) {
  return [];
}

return [{ json: { config, manual, hour, weekday } }];

// Builds, for each active user, the list of feeds that match their topics and
// scope, and the list of distinct feed URLs to fetch once per run.
const norm = (v) => String(v ?? '').trim();
const lower = (v) => norm(v).toLowerCase();
const isTrue = (v) => norm(v).toUpperCase() === 'TRUE';

const feeds = $('Feeds')
  .all()
  .map((i) => i.json)
  .filter((f) => norm(f.url) && isTrue(f.active))
  .map((f) => ({
    name: norm(f.name),
    url: norm(f.url),
    topic: lower(f.topic),
    scope: lower(f.scope),
    language: lower(f.language),
  }));

const topicsByUser = {};
for (const { json: t } of $('Topics').all()) {
  const email = lower(t.user_email);
  const topic = lower(t.topic);
  if (!email || !topic) continue;
  topicsByUser[email] ??= [];
  if (!topicsByUser[email].includes(topic)) topicsByUser[email].push(topic);
}

const users = $('Users')
  .all()
  .map((i) => i.json)
  .filter((u) => norm(u.email) && isTrue(u.active))
  .map((u) => {
    const email = norm(u.email);
    const topics = topicsByUser[email.toLowerCase()] ?? [];
    const scope = lower(u.scope);
    const count = Math.trunc(Number(u.news_count));
    return {
      email,
      name: norm(u.name),
      language: lower(u.language) === 'es' ? 'es' : 'en',
      level: norm(u.level).toUpperCase(),
      scope,
      newsCount: Math.min(15, Math.max(1, Number.isFinite(count) ? count : 1)),
      topics,
      feeds: feeds.filter(
        (f) => topics.includes(f.topic) && (scope === 'both' || f.scope === scope),
      ),
    };
  });

const feedUrls = [...new Set(users.flatMap((u) => u.feeds.map((f) => f.url)))];

return [{ json: { users, feedUrls } }];

// Picks each user's articles from the fetched feeds: age filter, de-duplication
// by link, and round-robin across the user's topics, newest first.
const norm = (v) => String(v ?? '').trim();
const stripHtml = (v) => norm(v).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const { config } = $('Schedule Check').first().json;
const { users } = $('Build Plan').first().json;
const feedUrls = $('Feed URLs').all().map((i) => i.json.url);

const maxAgeHours = Number(config.max_article_age_hours);
const minTime = Date.now() - (maxAgeHours > 0 ? maxAgeHours : 24) * 3600 * 1000;

// Each fetched item is linked to the feed URL it came from through pairedItem.
// It is read from the Fetch Feeds output and not from $input, because n8n
// renumbers pairedItem on the items a node receives.
// A feed that failed arrives as a single item with only an `error` field.
const itemsByUrl = {};
for (const item of $('Fetch Feeds').all()) {
  const paired = [item.pairedItem].flat()[0];
  const url = feedUrls[typeof paired === 'number' ? paired : paired?.item];
  const link = norm(item.json.link);
  const time = Date.parse(item.json.isoDate ?? item.json.pubDate ?? '');
  if (!url || !link || Number.isNaN(time) || time < minTime) continue;
  itemsByUrl[url] ??= [];
  itemsByUrl[url].push({
    link,
    time,
    originalTitle: norm(item.json.title),
    originalSnippet: stripHtml(item.json.contentSnippet ?? item.json.content),
  });
}

return users.map(({ feeds, ...user }) => {
  const seen = new Set();
  const queues = user.topics.map((topic) =>
    feeds
      .filter((f) => f.topic === topic)
      .flatMap((f) => (itemsByUrl[f.url] ?? []).map((a) => ({ ...a, topic, source: f.name })))
      .sort((a, b) => b.time - a.time),
  );

  const articles = [];
  while (articles.length < user.newsCount && queues.some((q) => q.length)) {
    for (const queue of queues) {
      if (articles.length >= user.newsCount) break;
      let next = queue.shift();
      while (next && seen.has(next.link)) next = queue.shift();
      if (!next) continue;
      seen.add(next.link);
      articles.push({
        topic: next.topic,
        source: next.source,
        link: next.link,
        publishedAt: DateTime.fromMillis(next.time)
          .setZone('America/Bogota')
          .toISO({ suppressMilliseconds: true }),
        originalTitle: next.originalTitle,
        originalSnippet: next.originalSnippet,
        title: next.originalTitle,
        summary: next.originalSnippet,
        aiOk: false,
      });
    }
  }

  return { json: { user, articles } };
});

// Builds one Ollama request per selected article, in the user's language and level.
const { config } = $('Schedule Check').first().json;
const model = config.ollama_model || 'gemma4:12b';

const requests = [];
for (const { json } of $input.all()) {
  const { user, articles } = json;
  const level = ['B1', 'B2', 'C1'].includes(user.level) ? user.level : 'B2';
  const target =
    user.language === 'es'
      ? 'Spanish'
      : `English at CEFR level ${level}, with vocabulary and grammar that fit that level`;

  articles.forEach((article, articleIndex) => {
    const prompt = [
      'You rewrite news items for a daily email digest.',
      `Write in ${target}. If the news item is in another language, translate it.`,
      'Use only the facts in the title and text given below. Do not add any detail that is not there.',
      'Answer with JSON only, in this shape: {"title": "...", "summary": "..."}',
      'The title is one short line. The summary is 2 or 3 sentences.',
      '',
      `Title: ${article.originalTitle}`,
      `Text: ${article.originalSnippet}`,
    ].join('\n');

    requests.push({
      json: {
        userEmail: user.email,
        articleIndex,
        request: { model, prompt, format: 'json', stream: false, think: false },
      },
    });
  });
}

return requests;

// Puts each Ollama answer back into its article. An article whose call failed or
// returned invalid JSON keeps the original title and snippet, with aiOk = false.
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// The loop returns one result per request, in the same order.
const requests = $('Summary Prompts').all();
const results = $input.all();
const inOrder = results.length === requests.length;

let next = 0;
return $('Select Articles')
  .all()
  .map(({ json }) => ({
    json: {
      user: json.user,
      articles: json.articles.map((article) => {
        const result = inOrder ? results[next].json : {};
        next += 1;
        let answer = {};
        try {
          answer = JSON.parse(result.response) ?? {};
        } catch (error) {
          // Failed call or invalid JSON: fall back below.
        }
        const title = text(answer.title);
        const summary = text(answer.summary);
        return title && summary ? { ...article, title, summary, aiOk: true } : article;
      }),
    },
  }));

// Builds one item per user. Users who read in English get an Ollama request for
// the vocabulary box, made from the summaries the AI wrote for them today.
const { config } = $('Schedule Check').first().json;
const model = config.ollama_model || 'gemma4:12b';

return $input.all().map(({ json }) => {
  const { user, articles } = json;
  const summaries = articles.filter((a) => a.aiOk).map((a) => `- ${a.title}. ${a.summary}`);
  const wantsVocabulary = user.language === 'en' && summaries.length > 0;
  if (!wantsVocabulary) return { json: { userEmail: user.email, wantsVocabulary } };

  const level = ['B1', 'B2', 'C1'].includes(user.level) ? user.level : 'B2';
  const prompt = [
    'You help a Spanish speaker who is learning English.',
    `From the news summaries below, choose the 5 most difficult English words or expressions for a learner at CEFR level ${level}.`,
    'Choose only words that appear in the summaries. Do not choose names of people, places or companies.',
    'For each one, give its meaning in Spanish and one short example sentence in English.',
    'Answer with JSON only, in this shape: {"vocabulary": [{"word": "...", "meaning_es": "...", "example": "..."}]}',
    '',
    'Summaries:',
    ...summaries,
  ].join('\n');

  return {
    json: {
      userEmail: user.email,
      wantsVocabulary,
      request: { model, prompt, format: 'json', stream: false, think: false },
    },
  };
});

// Adds the vocabulary list to each user. It stays empty for users who read in
// Spanish, and when the Ollama call failed or returned invalid JSON.
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// The loop returns one result per user, in the same order.
const requests = $('Vocabulary Prompts').all();
const results = $input.all();
const inOrder = results.length === requests.length;

return $('Apply Summaries')
  .all()
  .map(({ json }, i) => {
    let vocabulary = [];
    if (inOrder && requests[i].json.wantsVocabulary) {
      try {
        const answer = JSON.parse(results[i].json.response) ?? {};
        vocabulary = (Array.isArray(answer.vocabulary) ? answer.vocabulary : [])
          .map((v) => ({
            word: text(v?.word),
            meaning_es: text(v?.meaning_es),
            example: text(v?.example),
          }))
          .filter((v) => v.word && v.meaning_es && v.example)
          .slice(0, 5);
      } catch (error) {
        // Failed call or invalid JSON: no vocabulary box.
      }
    }
    return { json: { ...json, vocabulary } };
  });

// Renders one HTML email per user from their articles and vocabulary, with the
// labels in the user's language. Styles are inline, so a client that drops
// <style> still shows the full layout. <style> holds only the rule that reduces
// the side padding on phones.
const WIDTH = 760; // max width of the column, and fixed width in Outlook

const LABELS = {
  en: {
    subject: 'Your news',
    greeting: 'Hello',
    intro: 'Here is your news for today.',
    read: 'Read the original',
    vocabulary: 'Vocabulary',
    footer:
      'The summaries are written by an AI from the title and the short text of each feed. Read the original for the full story.',
    topics: {},
  },
  es: {
    subject: 'Tus noticias',
    greeting: 'Hola',
    intro: 'Estas son tus noticias de hoy.',
    read: 'Leer el original',
    vocabulary: 'Vocabulario',
    footer:
      'Los resúmenes los escribe una IA a partir del título y el texto corto de cada fuente. Lee el original para ver la noticia completa.',
    topics: {
      technology: 'Tecnología',
      politics: 'Política',
      economy: 'Economía',
      sports: 'Deportes',
      health: 'Salud',
      science: 'Ciencia',
      culture: 'Cultura',
    },
  },
};

const FONT = "font-family:Arial,Helvetica,sans-serif;";
const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
const safeLink = (v) => (/^https?:\/\//i.test(v) ? esc(v) : '#');

const today = DateTime.now().setZone('America/Bogota');

return $input.all().map(({ json }) => {
  const { user, articles, vocabulary } = json;
  const t = LABELS[user.language] ?? LABELS.en;
  const topicLabel = (topic) => t.topics[topic] ?? topic.charAt(0).toUpperCase() + topic.slice(1);
  const when = (iso) =>
    DateTime.fromISO(iso, { setZone: true }).setLocale(user.language).toFormat('d LLL, HH:mm');

  const cards = articles
    .map(
      (a) => `
        <tr><td style="padding:0 0 16px 0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e3e6ea;border-radius:8px;">
            <tr><td class="px-inner" style="padding:18px 20px;${FONT}">
              <div style="font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#1a5fb4;">${esc(topicLabel(a.topic))}</div>
              <div style="font-size:19px;line-height:25px;font-weight:bold;color:#1c2024;padding:6px 0 8px 0;">${esc(a.title)}</div>
              <div style="font-size:16px;line-height:24px;color:#3b4148;">${esc(a.summary)}</div>
              <div style="font-size:13px;line-height:20px;color:#6b7280;padding-top:12px;">${esc(a.source)} · ${esc(when(a.publishedAt))}</div>
              <div style="font-size:15px;line-height:22px;padding-top:4px;"><a href="${safeLink(a.link)}" style="color:#1a5fb4;font-weight:bold;text-decoration:underline;">${t.read} →</a></div>
            </td></tr>
          </table>
        </td></tr>`,
    )
    .join('');

  const words = (vocabulary ?? [])
    .map(
      (v) => `
              <div style="padding-top:12px;font-size:16px;line-height:23px;color:#1c2024;"><b>${esc(v.word)}</b> — ${esc(v.meaning_es)}</div>
              <div style="font-size:15px;line-height:22px;color:#5b5346;font-style:italic;">${esc(v.example)}</div>`,
    )
    .join('');
  const vocabularyBox = words
    ? `
        <tr><td style="padding:0 0 16px 0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fff8e6;border:1px solid #f0dca8;border-radius:8px;">
            <tr><td class="px-inner" style="padding:18px 20px;${FONT}">
              <div style="font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8a5a00;">${t.vocabulary}</div>${words}
            </td></tr>
          </table>
        </td></tr>`
    : '';

  const subject = `${t.subject} — ${today.toFormat('yyyy-MM-dd')}`;
  const html = `<!DOCTYPE html>
<html lang="${user.language}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${subject}</title>
<style>
  @media (max-width:480px) {
    .px-outer { padding-left:4px !important; padding-right:4px !important; }
    .px-inner { padding-left:14px !important; padding-right:14px !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background:#f2f4f7;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f4f7;">
    <tr><td class="px-outer" align="center" style="padding:16px 12px;">
      <!--[if mso]><table role="presentation" width="${WIDTH}" align="center" cellpadding="0" cellspacing="0"><tr><td><![endif]-->
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:${WIDTH}px;">
        <tr><td style="padding:8px 4px 20px 4px;${FONT}">
          <div style="font-size:26px;line-height:32px;font-weight:bold;color:#1c2024;">${t.subject}</div>
          <div style="font-size:14px;line-height:20px;color:#6b7280;">${esc(today.setLocale(user.language).toFormat('DDDD'))}</div>
          <div style="font-size:16px;line-height:24px;color:#3b4148;padding-top:12px;">${t.greeting}${user.name ? ' ' + esc(user.name) : ''}. ${t.intro}</div>
        </td></tr>${cards}${vocabularyBox}
        <tr><td style="padding:4px 4px 16px 4px;${FONT}font-size:12px;line-height:18px;color:#6b7280;">${t.footer}</td></tr>
      </table>
      <!--[if mso]></td></tr></table><![endif]-->
    </td></tr>
  </table>
</body>
</html>`;

  return { json: { email: user.email, subject, html, articleCount: articles.length } };
});
